"""Unified formula library and on-demand matching against retained OEIS exports."""
import csv
import hashlib
from html import escape as e
import io
import json
from pathlib import Path
import shutil
from zipfile import ZipFile,ZipInfo,ZIP_DEFLATED
from sequence_formula_catalogue import expanded_catalogue, formula_variants, formula_block, REGISTRY_PATH
from sequence_archive import records, plot_section
from sequence_research_tables import cell_coordinates, triangle_section


def source_degree(entry,n):
    if entry.get('triangle'):
        row,_=cell_coordinates(entry,n);return row*entry['triangle']['degree_multiplier']
    if 'source_shift' in entry:return entry['N']*n+entry['source_shift']
    if entry['kind']=='logarithmic companion':return entry['N']*(n+1)-1
    if entry['kind'].startswith('Appell '):return n
    return entry['N']*n+(entry.get('j',0) if entry['kind']=='classical multisection' else 0)


def library_entries(atlas):
    groups=[('atlas',atlas,'sequences/'),('recovered',records(atlas),'sequence-archive/'),('formulas',expanded_catalogue(),'sequence-families/')]
    entries=[]
    for collection,values,prefix in groups:
        for original in values:
            entry=dict(original,collection=collection,url=prefix+original['id']+'.html')
            entry.setdefault('source','https://komorebip.github.io/Operation-KOMOREBI/'+entry['url']+'#definition')
            entry.setdefault('index_symbol','n');entry.setdefault('classification','family' if collection=='formulas' else 'reference')
            if entry['id']=='KOM084':entry['tags']=[*entry['tags'],'triangle']
            entry['formulas']=formula_variants(entry)
            entries.append(entry)
    return entries


def matches_block(entry):
    hits=entry.get('matches',[]);total=entry.get('match_count',len(hits))
    return '<section id="oeis-matches"><h2>OEIS comparisons</h2><p>Exact finite matches, starting at local index '+str(entry['offset'])+'. Excerpt positions below count from zero in the bulk export; they are not OEIS mathematical offsets. Matching terms do not prove infinite sequence identity.</p>'+(
        '<ol>'+''.join('<li><a href="https://oeis.org/'+x['id']+'">'+x['id']+'</a> — '+e(x['name'])+'<br>'+str(x['matched_terms'])+' matching terms · OEIS excerpt position '+str(x['position'])+'</li>' for x in hits[:8])+'</ol><p>Showing '+str(min(8,len(hits)))+' of '+str(total)+' observed hits. Up to 50 ranked hits are retained in the entry JSON.</p>' if hits else '<p>No eight-term contiguous match was found in the recorded export. This does not establish novelty.</p>')+'<p>Reference names and terms: <a href="https://oeis.org/">The Online Encyclopedia of Integer Sequences</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Matching and presentation are adaptations.</p></section>'


def build(site,atlas):
    entries=library_entries(atlas)
    snapshot=json.loads((site.root/'manifests/sequence-library-oeis.json').read_text(encoding='utf-8'))
    signature=hashlib.sha256(json.dumps([(x['id'],x['terms']) for x in entries],separators=(',',':')).encode()).hexdigest()
    if signature!=snapshot['catalogue_terms_sha256']:raise ValueError('Regenerate the full-library OEIS comparison after term changes')
    for entry in entries:
        entry['matches']=snapshot['matches'].get(entry['id'],[]);entry['match_count']=snapshot['total_matches'].get(entry['id'],0)
        entry['oeis_snapshot']=dict(attribution=snapshot['attribution'],license=snapshot['license'],source_urls=snapshot['source_urls'],downloaded_at=snapshot['snapshot']['downloaded_at'],stripped_sha256=snapshot['stripped_sha256'],names_sha256=snapshot['names_sha256'],scope='Finite contiguous comparisons; export positions are not mathematical offsets and matches do not prove infinite identity.')
    source=site.root/'research/oeis-snapshot'
    target=site.output/'assets/oeis';target.mkdir(parents=True,exist_ok=True)
    for file in snapshot['snapshot']['files']:
        raw=(source/file['file']).read_bytes()
        if hashlib.sha256(raw).hexdigest()!=file['sha256']:raise ValueError('OEIS snapshot hash differs: '+file['file'])
        shutil.copyfile(source/file['file'],target/file['file'])
    site.write('assets/oeis/snapshot.json',json.dumps(snapshot['snapshot'],indent=2)+'\n')
    data=dict(schema=1,entries=entries,snapshot={key:value for key,value in snapshot.items() if key not in ('matches','total_matches')})
    site.write('assets/sequence-library-data.json',json.dumps(data,ensure_ascii=False,separators=(',',':'))+'\n')
    site.write('assets/sequence-formulas.json',json.dumps({x['id']:x['formulas'] for x in entries},ensure_ascii=False,separators=(',',':'))+'\n')
    out=io.StringIO(newline='');writer=csv.writer(out);writer.writerow(['id','title','collection','family','offset','stored_terms','representations','entry_url'])
    for x in entries:writer.writerow([x['id'],x['title'],x['collection'],x['kind'],x['offset'],len(x['terms']),len(x['formulas']),x['url']])
    site.write('assets/sequence-library-index.csv',out.getvalue())
    source_files=['tools/'+name+'.py' for name in ['sequence_formula_catalogue','sequence_research_tables','sequence_atlas','sequence_atlas_reference','sequence_atlas_reading','sequence_atlas_study','sequence_atlas_index']]+[REGISTRY_PATH]
    with ZipFile(site.output/'assets/sequence-formula-source.zip','w',ZIP_DEFLATED) as bundle:
        for name in source_files:
            info=ZipInfo(name,date_time=(2026,11,15,0,0,0));info.compress_type=ZIP_DEFLATED;info.external_attr=0o100644<<16;bundle.writestr(info,(site.root/name).read_text(encoding='utf-8').encode('utf-8'))
        info=ZipInfo('README.txt',date_time=(2026,11,15,0,0,0));info.compress_type=ZIP_DEFLATED;info.external_attr=0o100644<<16
        bundle.writestr(info,'Exact formula catalogue. Python 3.10+ standard library. Text sources use UTF-8/LF for portable reproduction.\nRun: python tools/sequence_formula_catalogue.py --id KFOR-S-catalan-03-01\nExport all records: python tools/sequence_formula_catalogue.py --output records.json\nScalar records store 24 terms beginning at their explicit offsets. Coefficient triangles store complete rows n=0..12, including zeros. Triangle j is a flat cell index; n and k are the row and column. Parameter records are not claims of novelty or pairwise distinctness.\n')
    scripts=['math-display.mjs','sequence-reading-theme.mjs','sequence-oeis-core.mjs','sequence-oeis-worker.mjs','sequence-oeis-client.mjs','sequence-workbench-core.mjs','sequence-workbench.mjs','sequence-library.js']
    for name in scripts:
        content=(site.root/'website/assets'/name).read_text(encoding='utf-8')
        content=content.replace('__OEIS_TERMS_SHA256__',snapshot['stripped_sha256']).replace('__OEIS_NAMES_SHA256__',snapshot['names_sha256'])
        for dep in scripts+['sequence-atlas-search.mjs','sequence-archive-plot.mjs','sequence-atlas-core.mjs','sequence-atlas-saved.mjs','sequence-plot-options.mjs']:
            path=site.output/'assets'/dep
            if path.exists():content=content.replace("'./"+dep+"'","'./"+dep+'?v='+hashlib.sha256(path.read_bytes()).hexdigest()[:12]+"'")
        site.write('assets/'+name,content)
    site.write('assets/sequence-library.css',(site.root/'website/assets/sequence-library.css').read_text(encoding='utf-8'))
    def wrap(body,prefix='',entry=None):
        attrs=' data-entry="'+e(entry['id'])+'.json"' if entry else ''
        return ''.join('<link rel="stylesheet" href="'+prefix+'assets/'+name+'?v='+hashlib.sha256((site.output/'assets'/name).read_bytes()).hexdigest()[:12]+'">' for name in ['sequence-archive.css','sequence-plot-options.css','sequence-library.css','sequence-reading.css'])+'<div class="sar sl-library" data-library'+attrs+'>'+body+'</div><script type="module" src="'+prefix+'assets/sequence-library.js?v='+hashlib.sha256((site.output/'assets/sequence-library.js').read_bytes()).hexdigest()[:12]+'"></script>'
    total=len(entries);representations=sum(len(x['formulas']) for x in entries)
    kinds=sorted({x['kind'] for x in entries});types=sorted({f['kind'] for x in entries for f in x['formulas']});statuses=sorted({x['status'] for x in entries})
    collections=[('', 'All records',total)]+[(key,label,sum(x['collection']==key for x in entries)) for key,label in [('formulas','Formula families'),('atlas','Curated sequences'),('recovered','Research archive')]]
    collection_buttons='<div class="sl-collections" role="group" aria-label="Search collections">'+''.join('<button type="button" data-collection="'+key+'" aria-pressed="'+('true' if not key else 'false')+'">'+label+' <span>'+f'{count:,}'+'</span></button>' for key,label,count in collections)+'</div>'
    header='<header class="sl-hero"><p class="sar-kicker">Komorebi / Sequence library</p><h1>Sequence library</h1><p class="sar-lede">Find integer sequences, compare formula representations, and explore exact values through interactive plots. Browse classical sequences and families from Komorebi research, or compare your terms with OEIS.</p><div class="sar-stats"><span><strong>'+f'{total:,}'+'</strong> sequence records</span><span><strong>'+f'{representations:,}'+'</strong> formula representations</span><span><strong>'+f'{snapshot["sequence_count"]:,}'+'</strong> OEIS reference records</span></div><nav aria-label="Library sections"><a href="#library-search">Search all sequences</a><a href="#oeis">Match with OEIS</a><a href="#comparison">Compare records</a><a href="sequence-explorer.html#explorer">Curated generators</a><a href="sequence-library/index.html">Complete index</a></nav></header>'
    research_count=sum('research-derived' in item['tags'] for item in entries)
    triangle_count=sum('triangle' in item['tags'] for item in entries)
    research='<section id="research-families"><h2>From our research</h2><p>'+str(research_count)+' records from families defined in our special-function registry: transfer-secancy parameter polynomials, Euler-transfer theta polynomials, and block-Appell coefficient tables and columns. Read the defining generator, follow the source index, and compare the exact coefficients. These definitions follow the published special-function registry; historical novelty remains unassessed.</p><p><a href="sequence-library.html?q=tag%3Atriangle#library-search">Browse coefficient triangles</a> · <a href="sequence-families/KFOR-TRI-P-03.html#triangle">Read the N=3 secancy triangle</a> · <a href="sequence-families/KFOR-TRI-A-03-01.html#triangle">Explore a block-Appell triangle</a></p><div class="sar-grid"><article class="sar-card"><h3>Secancy parameter columns</h3><p>88 records, N=2–12 and k=1–8. Extract the ordinary coefficient of r^k in P_(N,n)(r). Each window begins at n=k. For example, P_(3,2)(r)=9r+10r^2.</p><a href="sequence-families/KFOR-P-03-02.html">Explore N=3, k=2 →</a></article><article class="sar-card"><h3>Theta integer specializations</h3><p>12 records, x=1–12, from sech(xz) sech(z)^x. Local index n selects source degree 2n. At x=2 the first values are 1, −6, 144, −7536.</p><a href="sequence-families/KFOR-H-02.html">Explore x=2 →</a></article><article class="sar-card"><h3>Theta coefficient columns</h3><p>12 records extract x^k from Theta_(2n)(x). They retain their signs and start at n=ceil(k/2). The finite convolution formula connects them to the secancy parameter polynomials.</p><a href="sequence-families/KFOR-HC-04.html">Explore the x^4 column →</a></article></div></section>'
    controls='''<section id="library-search"><h2>Find a sequence or formula</h2><form id="sl-search" role="search" hidden>'''+collection_buttons+'''<label for="sl-query">Name, formula, identifier, or exact terms</label><div class="sl-query"><input id="sl-query" type="search" maxlength="20000" placeholder="Try hypergeometric, j:1 r:2, or 1, 1, 69" aria-describedby="sl-help sl-error"><button type="submit">Search</button><button id="sl-clear" type="button">Clear</button></div><details><summary>Filters and search options</summary><div class="sar-controls"><label for="sl-collection">Collection<select id="sl-collection"><option value="">All collections</option><option value="formulas">Formula families</option><option value="atlas">Curated sequences</option><option value="recovered">Research archive</option></select></label><label for="sl-kind">Family<select id="sl-kind"><option value="">All families</option>'''+''.join('<option>'+e(k)+'</option>' for k in kinds)+'''</select></label><label for="sl-representation">Formula type<select id="sl-representation"><option value="">All representations</option>'''+''.join('<option>'+e(k)+'</option>' for k in types)+'''</select></label><label for="sl-status">Review status<select id="sl-status"><option value="">All review statuses</option>'''+''.join('<option>'+e(status)+'</option>' for status in statuses)+'''</select></label><label for="sl-match">Term matching<select id="sl-match"><option value="any">Anywhere in stored terms</option><option value="start">At the first stored index</option></select></label><label for="sl-sort">Order<select id="sl-sort"><option value="relevance">Best match</option><option value="name">Name</option><option value="id">Identifier</option></select></label><label for="sl-hits">OEIS comparisons<select id="sl-hits"><option value="">All records</option><option value="matched">Has an eight-term reference match</option><option value="unmatched">No recorded eight-term match</option></select></label></div></details><div class="sp-actions"><button id="sl-research" type="button" hidden>Browse research families</button><button id="sl-triangles" type="button" hidden>Browse coefficient triangles ('+str(triangle_count)+')</button><button id="sl-share" type="button">Copy search link</button><button id="sl-export" type="button">Export results CSV</button></div><label id="sl-link-wrap" hidden for="sl-link">Copy this search link<input id="sl-link" readonly></label><p id="sl-error" role="alert" hidden></p><p id="sl-action-status" role="status" aria-live="polite"></p><div id="sl-active-filters" class="sl-active-filters" aria-label="Active search filters"></div></form><p id="sl-help">Words use AND; use | for alternatives, -word to exclude, and quotes for phrases. Fields include id:, name:, formula:, n: (spacing N), j:, r:, x:, k: (polynomial column), representation:, collection:, oeis: and terms:. Use ? for one unknown integer. All formula variants are searched. Matches retain original offsets.</p><p id="sl-count" role="status" aria-live="polite">Browse the <a href="sequence-library/index.html">complete static index</a> without JavaScript.</p><ol id="sl-results" class="sl-results"></ol><div id="sl-pages" class="sp-actions" hidden><button id="sl-previous" type="button">Previous results</button><span id="sl-page"></span><button id="sl-next" type="button">Next results</button></div></section>'''
    mb=sum(x['bytes'] for x in snapshot['snapshot']['files'])/1048576
    reference='''<section id="oeis" class="sl-reference"><p class="sar-kicker">Reference matching</p><h2>Compare with OEIS</h2><p>Search an A-number, words from a sequence name, or at least three comma-separated exact terms. ? matches one unknown integer. This tool uses the official terms and names exports from '''+e(snapshot['snapshot']['downloaded_at'][:10])+'''. Excerpt positions do not supply mathematical offsets.</p><form id="sl-oeis-form" hidden><label for="sl-oeis-query">OEIS ID, name, or integer pattern</label><div class="sl-query"><input id="sl-oeis-query" maxlength="20000" placeholder="A000108 or 1,1,2,5,14,42,132,429"><button id="sl-oeis-search" type="submit">Search OEIS data</button><button id="sl-oeis-cancel" type="button" disabled>Cancel</button></div></form><p>Loads about '''+f'{mb:.1f}'+''' MiB on your first search. Search runs in this browser; query terms are not sent to OEIS. Up to 50 results are displayed, with the total reported. The bulk files contain terms and names; open an OEIS entry for its formulas, comments, offset, and history.</p><p id="sl-oeis-status" role="status" aria-live="polite">Ready to search OEIS reference data.</p><ol id="sl-oeis-results"></ol><p>Downloads: <a download href="assets/oeis/stripped.gz">OEIS terms</a> · <a download href="assets/oeis/names.gz">OEIS names</a> · <a href="assets/oeis/snapshot.json">Dates, sizes and SHA-256 hashes</a></p><p>OEIS data © The OEIS Foundation Inc., <a href="https://oeis.org/">The Online Encyclopedia of Integer Sequences</a>, available under <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Reference matching and presentation are adaptations. <a href="https://oeis.org/wiki/Download">Official download guidance</a>.</p></section>'''
    about='<section id="library-sources"><h2>Definitions, scope, and downloads</h2><p>The '+str(len(expanded_catalogue()))+' parameter records cover reciprocal powers (N=2–16, r=1–8, complementing the curated sequences), transfer tangents (N=2–16), congruential coefficient components (N=2–12, 1≤j&lt;N, r=1–4), Appell components (N=2–6, 0≤j&lt;N, r=1–2, x=1 or 2), and classical multisections (N=2–12, 0≤j&lt;N). The research families include secancy parameter columns (N=2–12, k=1–8), theta specializations (x=1–12), and theta polynomial columns (k=1–12). Scalar records store 24 terms at their stated offsets; polynomial columns begin at their first nonzero n. The coefficient triangles preserve complete rows n=0–12, with separate row, column, and flat indices. The supported Appell columns retain their polynomial row map Nn+k. The other parameter records use n=0–23. Rational coefficients are explicitly reduced before taking a signed numerator or positive denominator. Every entry links to its definition and records its normalization.</p><p>Parameter records need not define distinct infinite sequences. Finite implementation checks do not establish novelty or prove identities from matching terms. Hypergeometric labels identify the actual representation: a term formula, a generating function, or coefficient extraction.</p><p><a download href="assets/sequence-library-index.csv">Complete index CSV</a> · <a download href="assets/sequence-formulas.json">All formula representations JSON</a> · <a download href="assets/sequence-formula-source.zip">Exact Python generator and defining source</a> · <a href="sequence-archive.html">Research archive and generator</a></p></section>'
    site.page('sequence-library.html','Sequence library',wrap(header+controls+research+'<section id="comparison"><h2>Compare records</h2><p>Enable JavaScript to compare up to four library records or OEIS excerpts, transform exact terms, and export plots. Definitions and exact tables remain available in the <a href="sequence-library/index.html">complete index</a>.</p></section>'+reference+about))
    rows=''.join('<tr><th scope="row"><a href="../'+x['url']+'">'+e(x['id'])+'</a></th><td>'+e(x['title'])+'</td><td>'+e(x['kind'])+'</td><td>'+str(len(x['formulas']))+'</td><td>'+str(x['offset'])+'</td></tr>' for x in entries)
    site.page('sequence-library/index.html','Complete sequence index',wrap('<nav><a href="../sequence-library.html">Search the library</a></nav><h1>Complete sequence index</h1><p>All '+str(total)+' local records. This index and all definitions and exact tables work without JavaScript.</p><div class="sar-scroll" tabindex="0" role="region" aria-label="Complete sequence index"><table><thead><tr><th scope="col">ID</th><th scope="col">Name</th><th scope="col">Family</th><th scope="col">Formulas</th><th scope="col">Offset</th></tr></thead><tbody>'+rows+'</tbody></table></div>','../'))
    for entry in entries:
        if entry['collection']!='formulas':continue
        identifier=entry['id'];start=entry['offset'];end=start+len(entry['terms'])-1
        site.write('sequence-families/'+identifier+'.json',json.dumps(entry,ensure_ascii=False,separators=(',',':'))+'\n')
        if entry.get('triangle'):
            site.write('sequence-families/'+identifier+'.csv','j,row_n,column_k,source_degree,value\n'+''.join(f'{j},{cell_coordinates(entry,j)[0]},{cell_coordinates(entry,j)[1]},{source_degree(entry,j)},{v}\n' for j,v in enumerate(entry['terms'])))
        else:site.write('sequence-families/'+identifier+'.csv','n,a(n)\n'+''.join(f'{n},{v}\n' for n,v in enumerate(entry['terms'],start=start)))
        site.write('sequence-families/'+identifier+'.txt','# '+identifier+' '+entry['title']+'\n'+''.join(f'{n} {v}\n' for n,v in enumerate(entry['terms'],start=start)))
        rational=entry.get('rational_terms')
        related=''.join('<p>Related local definition: <a href="'+e(x['id'])+'.html#definition">'+e(x['id'])+'</a>. '+e(x['note'])+'</p>' for x in entry.get('related_records',[]))
        coordinates=lambda n:('<td>'+str(cell_coordinates(entry,n)[0])+'</td><td>'+str(cell_coordinates(entry,n)[1])+'</td>') if entry.get('triangle') else ''
        index_label='Flat j' if entry.get('triangle') else 'Local n'
        value_label='a(j)' if entry.get('triangle') else 'a(n)'
        index_note=('The stored flat index is j='+str(start)+'–'+str(end)+'. Each row n contains columns k in increasing order. The source degree is computed from the row, not from j. ' if entry.get('triangle') else 'The local index is n='+str(start)+'–'+str(end)+'. The source degree/index map is '+e(entry['degree'])+'. ')+'The stored window contains exact integers; plotting never extrapolates. '+e(entry['explanation'])
        rows=''.join('<tr id="n-'+str(n)+'"><th scope="row">'+str(n)+'</th>'+coordinates(n)+'<td>'+str(source_degree(entry,n))+'</td><td>'+value+'</td>'+('<td>'+e(rational[n-start])+'</td>' if rational else '')+'</tr>' for n,value in enumerate(entry['terms'],start=start))
        body='<nav aria-label="Breadcrumb"><a href="../sequence-library.html">Sequence library</a> / '+e(identifier)+'</nav><header class="sar-header"><p class="sar-kicker">'+e(identifier)+' / Parameter record</p><h1>'+e(entry['title'])+'</h1><p>'+e(entry['status'])+'</p><nav aria-label="Entry sections"><a href="#definition">Definition</a><a href="#formulas">Formula representations</a>'+('<a href="#triangle">Coefficient triangle</a>' if entry.get('triangle') else '')+'<a href="#plot">Plot</a><a href="#exact-data">Exact data</a><a href="#oeis-matches">OEIS comparisons</a></nav></header><section id="definition"><h2>Definition and indexing</h2><p class="sar-formula">'+e(entry['formula'])+'</p><p>'+index_note+'</p>'+related+'</section><section id="formulas"><h2>Equivalent representations</h2>'+formula_block(entry)+'</section>'+triangle_section(entry)+plot_section(entry)+'<section id="exact-data"><h2>Exact indexed data</h2><p><a download href="'+identifier+'.csv">CSV</a> · <a download href="'+identifier+'.txt">Indexed text</a> · <a download href="'+identifier+'.json">Entry JSON with all formulas and comparisons</a></p><div class="sar-scroll" tabindex="0" role="region" aria-label="Exact stored values"><table><thead><tr><th scope="col">'+index_label+'</th>'+('<th scope="col">Row n</th><th scope="col">Column k</th>' if entry.get('triangle') else '')+'<th scope="col">Source degree/index</th><th scope="col">'+value_label+'</th>'+('<th scope="col">Original rational q(n)</th>' if rational else '')+'</tr></thead><tbody>'+rows+'</tbody></table></div></section>'+matches_block(entry)+'<section id="sources"><h2>Sources and reproduction</h2><p><a href="'+e(entry['source'])+'">Published construction source</a></p><p>Terms and representations follow the defining construction at the parameters shown. KFOR identifiers label records in this library; OEIS uses A-numbers.</p><details><summary>Reproduce this sequence</summary><p>Source: <code>'+REGISTRY_PATH+'</code>. Parameter grids and exact reproduction are implemented in <code>tools/sequence_formula_catalogue.py</code>. These finite software checks retain the scope of the defining source.</p><p><a download href="../assets/sequence-formula-source.zip">Download the exact Python generator and source</a>. Extract the bundle, then run <code>python tools/sequence_formula_catalogue.py --id '+identifier+'</code>.</p></details></section>'
        site.page(entry['url'],entry['title']+' · '+identifier,wrap(body,'../',entry))
        site.search.append(dict(title=entry['title']+' · '+identifier,group='Collection',kind='Examples',work_ids=[],url=entry['url'],text=' '.join(f['expression'] for f in entry['formulas'])))
    site.search.append(dict(title='Sequence library',group='Collection',kind='Examples',work_ids=[],url='sequence-library.html',text=f'{total} local records, {representations} formulas, hypergeometric representations, exact plots and full OEIS snapshot matching.'))
    return dict(entries=total,new_entries=len(expanded_catalogue()),formulas=representations,oeis_sequences=snapshot['sequence_count'],oeis_bytes=sum(x['bytes'] for x in snapshot['snapshot']['files']))
